bool search(Node* cur, const string& w, int i){
    if (i == w.size()) return cur->isEnd;
    char c = w[i];
    if (c == '.') {
        for (int d = 0; d < 26; d++)
            if (cur->ch[d] && search(cur->ch[d], w, i + 1)) return true;
        return false;
    }
    return cur->ch[c-'a'] && search(cur->ch[c-'a'], w, i+1);
}

