def search_wild(cur, w, i):
    if i == len(w): return cur.is_end
    c = w[i]
    if c == '.':
        return any(search_wild(child, w, i+1)
                   for child in cur.ch.values())
    child = cur.ch.get(c)
    return child is not None and search_wild(child, w, i+1)
